index c667ed83a..1c0b603ea 100644
--- a/packages/workflow/src/workflow-data-proxy.ts
+++ b/packages/workflow/src/workflow-data-proxy.ts
@@ -140,11 +140,16 @@ export class WorkflowDataProxy {
 		if (fullItem) return data;
 		if (this.workflow.settings?.binaryMode !== BINARY_MODE_COMBINED) return data;

+		// Results that are not shaped like an item (e.g. undefined for a missing
+		// pinned item) have no `json` to unwrap, so hand them back unchanged.
+		const unwrap = (item: INodeExecutionData) =>
+			item !== null && typeof item === 'object' && 'json' in item ? item.json : item;
+
 		if (Array.isArray(data)) {
-			return data.map((i) => i.json);
+			return data.map(unwrap);
 		}

-		return data.json;
+		return unwrap(data);
 	}

